{"command":"cd /workspace && cat > src/logging.rs <<'EOF'
//! Collection and printing of log messages

use colored::{ColoredString, Colorize};
use env_logger::Builder;
use log::Level;
use log::LevelFilter;
use std::io::Write;
use std::sync::atomic::{AtomicUsize, Ordering};

static LOG_COUNTER: AtomicUsize = AtomicUsize::new(0);

/// A single log entry, printed at the end of the run
#[derive(Debug, Clone)]
pub struct Log {
    pub level: Level,
    pub time: usize,
    pub file: String,
    pub message: String,
    pub linum_new: Option<usize>,
    pub linum_old: Option<usize>,
    pub line: Option<String>,
}

fn next_time() -> usize {
    LOG_COUNTER.fetch_add(1, Ordering::SeqCst)
}

/// Record a log entry which refers to a whole file
pub fn record_file_log(logs: &mut Vec<Log>, level: Level, file: &str, message: &str) {
    logs.push(Log {
        level,
        time: next_time(),
        file: file.to_string(),
        message: message.to_string(),
        linum_new: None,
        linum_old: None,
        line: None,
    });
}

/// Record a log entry which refers to a particular line
pub fn record_line_log(
    logs: &mut Vec<Log>,
    level: Level,
    file: &str,
    linum_new: usize,
    linum_old: usize,
    line: &str,
    message: &str,
) {
    logs.push(Log {
        level,
        time: next_time(),
        file: file.to_string(),
        message: message.to_string(),
        linum_new: Some(linum_new),
        linum_old: Some(linum_old),
        line: Some(line.to_string()),
    });
}

fn get_log_style(level: Level) -> ColoredString {
    match level {
        Level::Info => "INFO".cyan().bold(),
        Level::Warn => "WARN".yellow().bold(),
        Level::Error => "ERROR".red().bold(),
        Level::Trace => "TRACE".green().bold(),
        Level::Debug => "DEBUG".blue().bold(),
    }
}

/// Start the logger with the requested verbosity
pub fn init_logger(level: LevelFilter) {
    Builder::new()
        .filter_level(level)
        .format(|buf, record| {
            writeln!(buf, "{}: {}", get_log_style(record.level()), record.args())
        })
        .init();
}

/// Sort, deduplicate and print all recorded logs
pub fn print_logs(logs: &mut Vec<Log>) {
    logs.sort_by(|a, b| {
        (a.level, a.linum_new, a.linum_old, &a.message)
            .cmp(&(b.level, b.linum_new, b.linum_old, &b.message))
            .then(b.time.cmp(&a.time))
    });
    logs.dedup_by(|a, b| {
        a.level == b.level
            && a.linum_new == b.linum_new
            && a.linum_old == b.linum_old
            && a.message == b.message
            && a.file == b.file
            && a.line == b.line
    });
    logs.sort_by_key(|l| l.time);

    for log in logs.iter() {
        let linum_new = log
            .linum_new
            .map_or_else(String::new, |i| format!("Line {i} "));
        let linum_old = log
            .linum_old
            .map_or_else(String::new, |i| format!("({i}). "));
        let line = log
            .line
            .as_ref()
            .map_or_else(String::new, |l| l.trim_start().to_string());
        let log_string = format!(
            "{} {}: {}{}{} {}",
            "tex-fmt".magenta().bold(),
            log.file.blue().bold(),
            linum_new.white().bold(),
            linum_old.white().bold(),
            log.message.yellow().bold(),
            line,
        );
        match log.level {
            Level::Error => log::error!("{log_string}"),
            Level::Warn => log::warn!("{log_string}"),
            Level::Info => log::info!("{log_string}"),
            Level::Debug => log::debug!("{log_string}"),
            Level::Trace => log::trace!("{log_string}"),
        }
    }
}
EOF
echo ok"}

