        a.level == b.level
            && a.linum_new == b.linum_new
            && a.linum_old == b.linum_old
            && a.message == b.message
            && a.file == b.file
            && a.line == b.line
    });
    logs.sort_by_key(|l| l.time);

    for log in logs.iter() {
        let linum_new = log
            .linum_new
            .map_or_else(String::new, |i| format!("Line {i} "));
        let linum_old = log
            .linum_old
            .map_or_else(String::new, |i| format!("({i}). "));
        let line = log
            .line
            .as_ref()
            .map_or_else(String::new, |l| l.trim_start().to_string());
        let log_string = format!(
            "{} {}: {}{}{} {}",
            "tex-fmt".magenta().bold(),
            log.file.blue().bold(),
            linum_new.white().bold(),
            linum_old.white().bold(),
            log.message.yellow().bold(),
            line,
        );
        match log.level {
            Level::Error => log::error!("{log_string}"),
            Level::Warn => log::warn!("{log_string}"),
            Level::Info => log::info!("{log_string}"),
            Level::Debug => log::debug!("{log_string}"),
            Level::Trace => log::trace!("{log_string}"),
        }
    }
}
