        };
    };
    None
}

/// Get the root of a git repository
fn find_git_root() -> Option<PathBuf> {
    let mut depth = 0;
    let mut current_dir = current_dir().ok()?;
    loop {
        let mut git_dir = current_dir.clone();
        git_dir.push(".git");
        if git_dir.is_dir() {
            return Some(current_dir);
        }
        depth += 1;
        if !current_dir.pop() || depth > 4096 {
            return None;
        }
    }
}

/// The path of the config file which is in use, for display purposes
pub fn get_config_path(args: &OptionArgs) -> Option<PathBuf> {
    if args.noconfig == Some(true) {
        return args.config.clone();
    }
    resolve_config_path(args)
}

/// Read the contents of the config file
///
/// Returns the path of the file together with its text contents,
/// or `None` if no config file is to be read.
/// Panics if the file exists but cannot be read.
///
/// The config file is located by the following rules,
/// in order of decreasing priority:
///
/// - the file passed with `--config`
/// - `tex-fmt.toml` in the current directory
/// - `tex-fmt.toml` at the root of the current git repository
/// - `tex-fmt.toml` in the user config directory
fn get_config(args: &OptionArgs) -> Option<(PathBuf, String)> {
    let config_path = resolve_config_path(args)?;
    let config = std::fs::read_to_string(config_path.clone()).unwrap();
    Some((config_path, config))
}

/// Convert a list of TOML values into a list of strings
fn get_string_list(config: &Table, key: &str) -> Vec<String> {
    config
        .get(key)
        .and_then(|v| v.as_array())
        .map(|a| a.iter().filter_map(|v| v.as_str().map(String::from)).collect())
        .unwrap_or_default()
}

/// Convert a single-character string into a character
fn string_to_char(s: &str) -> char {
    let mut chars = s.chars();
    let c = chars.next().expect("String is empty");
    assert!(chars.next().is_none(), "String contains more than one character");
    c
}

