        wrap: config.get("wrap").map(|x| x.as_bool().unwrap()),
        wraplen: config
            .get("wraplen")
            .map(|x| x.as_integer().unwrap().try_into().unwrap()),
        wrapmin: config
            .get("wrapmin")
            .map(|x| x.as_integer().unwrap().try_into().unwrap()),
        tabsize: config
            .get("tabsize")
            .map(|x| x.as_integer().unwrap().try_into().unwrap()),
        tabchar,
        stdin: config.get("stdin").map(|x| x.as_bool().unwrap()),
        config: Some(config_file),
        noconfig: None,
        verbosity,
        arguments: None,
        files: vec![],
        recursive: None,
        lists: get_string_list(&config, "lists"),
        verbatims: get_string_list(&config, "verbatims"),
        no_indent_envs: get_string_list(&config, "no-indent-envs"),
        wrap_chars,
    };
    Some(args)
}
