//! Main arguments

use crate::cli::get_cli_args;
use crate::config::{get_config_args, get_config_path};
use crate::logging::{record_file_log, Log};
use crate::search::find_files;
use colored::Colorize;
use log::Level::Error;
use log::LevelFilter;
use std::fmt;
use std::path::PathBuf;

/// Character to use for indentation
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TabChar {
    Tab,
    Space,
}

impl fmt::Display for TabChar {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            Self::Tab => write!(f, "tab"),
            Self::Space => write!(f, "space"),
        }
    }
}

/// Fully resolved arguments
#[derive(Clone, Debug)]
pub struct Args {
    pub check: bool,
    pub print: bool,
    pub fail_on_change: bool,
    pub wrap: bool,
    pub wraplen: usize,
    pub wrapmin: usize,
    pub tabsize: u8,
    pub tabchar: TabChar,
    pub stdin: bool,
    pub config: Option<PathBuf>,
    pub noconfig: bool,
    pub verbosity: LevelFilter,
    pub arguments: bool,
    pub files: Vec<PathBuf>,
    pub recursive: bool,
    pub lists: Vec<String>,
    pub verbatims: Vec<String>,
    pub no_indent_envs: Vec<String>,
    pub wrap_chars: Vec<char>,
}

/// Arguments which may or may not have been provided
#[derive(Clone, Debug, Default)]
pub struct OptionArgs {
    pub check: Option<bool>,
    pub print: Option<bool>,
    pub fail_on_change: Option<bool>,
    pub wrap: Option<bool>,
    pub wraplen: Option<usize>,
    pub wrapmin: Option<usize>,
    pub tabsize: Option<u8>,
    pub tabchar: Option<TabChar>,
    pub stdin: Option<bool>,
    pub config: Option<PathBuf>,
    pub noconfig: Option<bool>,
    pub verbosity: Option<LevelFilter>,
    pub arguments: Option<bool>,
    pub files: Vec<PathBuf>,
    pub recursive: Option<bool>,
    pub lists: Vec<String>,
    pub verbatims: Vec<String>,
    pub no_indent_envs: Vec<String>,
    pub wrap_chars: Vec<char>,
}

const DEFAULT_LISTS: [&str; 5] = [
    "itemize",
    "enumerate",
    "description",
    "inlineroman",
    "inventory",
];

const DEFAULT_VERBATIMS: [&str; 5] =
    ["verbatim", "Verbatim", "lstlisting", "minted", "comment"];

const DEFAULT_NO_INDENT_ENVS: [&str; 1] = ["document"];

const DEFAULT_WRAP_CHARS: [char; 1] = [' '];

fn verbosity_name(v: LevelFilter) -> &'static str {
    match v {
        LevelFilter::Off => "off",
        LevelFilter::Error => "error",
        LevelFilter::Warn => "warn",
        LevelFilter::Info => "info",
        LevelFilter::Debug => "debug",
        LevelFilter::Trace => "trace",
    }
}

/// Collect the arguments from the command line and config file
pub fn get_args() -> Args {
    let cli_args = get_cli_args();
    let config_args = get_config_args(&cli_args);
    let config_path = get_config_path(&cli_args);
    let mut args = match config_args {
        Some(c) => merge(cli_args, c),
        None => cli_args,
    };
    args.config = config_path;
    resolve(args)
}

/// Combine two sets of arguments, preferring the first
fn merge(a: OptionArgs, b: OptionArgs) -> OptionArgs {
    let mut lists = a.lists;
    lists.extend(b.lists);
    let mut verbatims = a.verbatims;
    verbatims.extend(b.verbatims);
    let mut no_indent_envs = a.no_indent_envs;
    no_indent_envs.extend(b.no_indent_envs);
    let mut wrap_chars = a.wrap_chars;
    wrap_chars.extend(b.wrap_chars);
    OptionArgs {
        check: a.check.or(b.check),
        print: a.print.or(b.print),
        fail_on_change: a.fail_on_change.or(b.fail_on_change),
        wrap: a.wrap.or(b.wrap),
        wraplen: a.wraplen.or(b.wraplen),
        wrapmin: a.wrapmin.or(b.wrapmin),
        tabsize: a.tabsize.or(b.tabsize),
        tabchar: a.tabchar.or(b.tabchar),
        stdin: a.stdin.or(b.stdin),
        config: a.config.or(b.config),
        noconfig: a.noconfig.or(b.noconfig),
        verbosity: a.verbosity.or(b.verbosity),
        arguments: a.arguments.or(b.arguments),
        files: if a.files.is_empty() { b.files } else { a.files },
        recursive: a.recursive.or(b.recursive),
        lists,
        verbatims,
        no_indent_envs,
        wrap_chars,
    }
}

/// Fill in default values and locate files
fn resolve(args: OptionArgs) -> Args {
    let wraplen = args.wraplen.unwrap_or(80);
    let wrapmin = match args.wrapmin {
        Some(w) => w.min(wraplen),
        None => {
            if wraplen >= 50 {
                wraplen - 10
            } else {
                wraplen
            }
        }
    };
    let mut lists = args.lists;
    lists.extend(DEFAULT_LISTS.iter().map(|s| (*s).to_string()));
    let mut verbatims = args.verbatims;
    verbatims.extend(DEFAULT_VERBATIMS.iter().map(|s| (*s).to_string()));
    let mut no_indent_envs = args.no_indent_envs;
    no_indent_envs
        .extend(DEFAULT_NO_INDENT_ENVS.iter().map(|s| (*s).to_string()));
    let mut wrap_chars = args.wrap_chars;
    wrap_chars.extend(DEFAULT_WRAP_CHARS);

    let recursive = args.recursive.unwrap_or(false);

    // Add a .tex extension to files without an extension
    let mut files: Vec<PathBuf> = args.files;
    for file in &mut files {
        if file.extension().is_none() && !file.is_dir() {
            file.set_extension("tex");
        }
    }

    // Search for files recursively
    if recursive {
        files = find_files(files);
    }

    Args {
        check: args.check.unwrap_or(false),
        print: args.print.unwrap_or(false),
        fail_on_change: args.fail_on_change.unwrap_or(false),
        wrap: args.wrap.unwrap_or(true),
        wraplen,
        wrapmin,
        tabsize: args.tabsize.unwrap_or(2),
        tabchar: args.tabchar.unwrap_or(TabChar::Space),
        stdin: args.stdin.unwrap_or(false),
        config: args.config,
        noconfig: args.noconfig.unwrap_or(false),
        verbosity: args.verbosity.unwrap_or(LevelFilter::Warn),
        arguments: args.arguments.unwrap_or(false),
        files,
        recursive,
        lists,
        verbatims,
        no_indent_envs,
        wrap_chars,
    }
}

impl Args {
    /// Check the arguments for problems, returning an exit code
    pub fn validate(&self, logs: &mut Vec<Log>) -> u8 {
        let mut exit_code = 0;

        // Directories are only permitted with --recursive
        if !self.recursive && self.files.iter().any(|f| f.is_dir()) {
            record_file_log(
                logs,
                Error,
                "",
                "A directory was passed without --recursive.",
            );
            exit_code = 1;
        }

        // Do not pass both files and --stdin
        if self.stdin && !self.files.is_empty() {
            record_file_log(
                logs,
                Error,
                "",
                "Do not provide file name(s) when using --stdin.",
            );
            exit_code = 1;
        }

        // Some input must be provided
        if !self.stdin && self.files.is_empty() {
            record_file_log(
                logs,
                Error,
                "",
                "No files specified. Provide filenames, or pass --recursive or --stdin.",
            );
            exit_code = 1;
        }

        exit_code
    }
}

fn display_arg_line(f: &mut fmt::Formatter, name: &str, value: &str) -> fmt::Result {
    let s = format!("{}:", name.bold());
    writeln!(f, "  {s:<25}{value}")
}

fn display_arg_line_list(
    f: &mut fmt::Formatter,
    name: &str,
    values: &[String],
) -> fmt::Result {
    let s = format!("{}:", name.bold());
    match values.first() {
        Some(first) => writeln!(f, "  {s:<25}{first}")?,
        None => writeln!(f, "  {s:<25}")?,
    }
    for value in values.iter().skip(1) {
        let s = format!("{}", "".bold());
        writeln!(f, "  {s:<25}{value}")?;
    }
    Ok(())
}

impl fmt::Display for Args {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
