//! Recursive search for files to format

use ignore::WalkBuilder;
use std::path::PathBuf;

/// File extensions which are formatted in recursive mode
const EXTENSIONS: [&str; 4] = ["tex", "bib", "sty", "cls"];

fn has_valid_extension(path: &std::path::Path) -> bool {
    path.extension()
        .and_then(|e| e.to_str())
        .is_some_and(|e| EXTENSIONS.contains(&e))
}

/// Expand directories into the files they contain
///
/// Plain files are kept in their original order,
/// followed by the files found in each directory.
pub fn find_files(files: Vec<PathBuf>) -> Vec<PathBuf> {
    let files = if files.is_empty() {
        vec![PathBuf::from(".")]
    } else {
        files
    };
    let mut new_files: Vec<PathBuf> = vec![];
    let mut dirs: Vec<PathBuf> = vec![];
    for file in files {
        if file.is_file() {
            new_files.push(file);
        } else {
            dirs.push(file);
        }
    }
    for dir in dirs {
        for entry in WalkBuilder::new(&dir).build().flatten() {
            let is_file = entry.file_type().is_some_and(|t| t.is_file());
            if is_file && has_valid_extension(entry.path()) {
                new_files.push(entry.path().to_path_buf());
            }
        }
    }
    new_files
}
EOF
