//! Ignoring lines with `% tex-fmt: skip` and blocks with `off` / `on`

use crate::format::State;
use crate::logging::{record_line_log, Log};
use log::Level::Warn;

/// Ignore state of a line
#[derive(Clone, Debug, Default)]
pub struct Ignore {
    /// Whether an ignore block is currently open
    pub actual: bool,
    /// Whether this line should be left untouched
    pub visual: bool,
}

/// Determine the ignore state of a line
pub fn get_ignore(line: &str, state: &State, logs: &mut Vec<Log>, file: &str) -> Ignore {
    let skip = line.ends_with("% tex-fmt: skip");
    let begin = line.ends_with("% tex-fmt: off");
    let end = line.ends_with("% tex-fmt: on");

    let actual: bool;
    let visual: bool;

    if skip {
        actual = state.ignore.actual;
        visual = true;
    } else if begin {
        actual = true;
        visual = true;
        if state.ignore.actual {
            record_line_log(
                logs,
                Warn,
                file,
                state.linum_new,
                state.linum_old,
                line,
                "Cannot begin ignore block:",
            );
        }
    } else if end {
        actual = false;
