//! Regular expressions and string constants

use regex::Regex;
use std::sync::LazyLock;

/// Match a LaTeX `\item`
pub const ITEM: &str = "\\item";
/// Match a LaTeX `\begin{...}`
pub const ENV_BEGIN: &str = "\\begin{";
/// Match a LaTeX `\end{...}`
pub const ENV_END: &str = "\\end{";
/// Acceptable LaTeX file extensions
pub const VERBS: [&str; 3] = ["\\verb|", "\\verb+", "\\mintinline"];

/// Patterns which should begin on a new line
const SPLITTING: &str = concat!(
    r"(?:\\begin\{",
    r"|\\end\{",
    r"|\\item(?:$|[^a-zA-Z])",
    r"|\\(?:sub){0,2}section\*?\{",
    r"|\\chapter\*?\{",
    r"|\\part\*?\{",
    r")"
);

/// Regex matching any splitting pattern
pub static RE_SPLITTING: LazyLock<Regex> =
    LazyLock::new(|| Regex::new(SPLITTING).unwrap());

/// Regex capturing the text before and after a splitting pattern
pub static RE_SPLITTING_SHARED_LINE_CAPTURE: LazyLock<Regex> =
    LazyLock::new(|| {
        Regex::new(&format!(r"(?P<prev>\S.*?)(?P<env>{SPLITTING}.*)")).unwrap()
    });

/// Regex matching three or more consecutive newlines
pub static RE_NEWLINES: LazyLock<Regex> =
    LazyLock::new(|| Regex::new(r"\n\n\n+").unwrap());

/// Regex matching trailing spaces
pub static RE_TRAIL: LazyLock<Regex> =
    LazyLock::new(|| Regex::new(r" +\n").unwrap());
