//! Handling of LaTeX comments

/// Find the byte index of the first unescaped percent sign
pub fn find_comment_index(line: &str) -> Option<usize> {
    if !line.contains('%') {
        return None;
    }
    let mut prev_c: Option<char> = None;
    for (i, c) in line.char_indices() {
        if c == '%' && prev_c != Some('\\') {
            return Some(i);
        }
        prev_c = Some(c);
    }
    None
}

/// Remove the comment from the end of a line
pub fn remove_comment(line: &str, comment_index: Option<usize>) -> &str {
    comment_index.map_or(line, |c| &line[..c])
}
