//! Calculation of indentation levels

use crate::args::Args;
use crate::comments::{find_comment_index, remove_comment};
use crate::format::{EnvLists, State};
use crate::logging::{record_line_log, Log};
use crate::pattern::Pattern;
use crate::regexes::{ENV_BEGIN, ENV_END, ITEM, VERBS};
use log::Level::{Trace, Warn};
use std::cmp::max;

/// Opening delimiters
const OPENS: [char; 3] = ['{', '(', '['];
/// Closing delimiters
const CLOSES: [char; 3] = ['}', ')', ']'];

/// Indentation state of a line
#[derive(Debug, Clone, Default)]
pub struct Indent {
    /// The indentation level carried to the following lines
    pub actual: i8,
    /// The indentation level of this line itself
    pub visual: i8,
}

/// Which environment patterns are present in the (comment-free) line
struct Envs {
    begin: bool,
    end: bool,
    item: bool,
}

fn get_envs(line: &str, pattern: &Pattern) -> Envs {
    let contains_verb = VERBS.iter().any(|v| line.contains(v));
    if contains_verb {
        return Envs {
            begin: false,
            end: false,
            item: false,
        };
    }
    Envs {
        begin: pattern.contains_env_begin && line.contains(ENV_BEGIN),
        end: pattern.contains_env_end && line.contains(ENV_END),
        item: pattern.contains_item && line.contains(ITEM),
    }
}

/// Change in indentation caused by this line
fn get_diff(line: &str, envs: &Envs, env_lists: &EnvLists) -> i8 {
    let mut diff: i8 = 0;
    if envs.begin {
        if !env_lists.no_indent_begin.iter().any(|r| line.contains(r)) {
            diff = 1;
            if env_lists.lists_begin.iter().any(|r| line.contains(r)) {
                diff = diff.wrapping_add(1);
            }
        }
    } else if envs.end
        && !env_lists.no_indent_end.iter().any(|r| line.contains(r))
    {
        diff = -1;
        if env_lists.lists_end.iter().any(|r| line.contains(r)) {
            diff = diff.wrapping_sub(1);
        }
    }
    for c in line.chars() {
        if OPENS.contains(&c) {
            diff = diff.wrapping_add(1);
        } else if CLOSES.contains(&c) {
            diff = diff.wrapping_sub(1);
        }
    }
    diff
}

/// How far this line should be dedented relative to the current indent
fn get_back(line: &str, envs: &Envs, state: &State, env_lists: &EnvLists) -> i8 {
    let mut back: i8 = 0;
    let mut cumul: i8 = 0;
    for c in line.chars() {
        if OPENS.contains(&c) {
            cumul = cumul.wrapping_sub(1);
        } else if CLOSES.contains(&c) {
            cumul = cumul.wrapping_add(1);
        }
        back = max(cumul, back);
    }

    // Environments only dedent if indentation is present
    if state.indent.actual == 0 {
        return back;
    }

    if envs.end {
        if env_lists.no_indent_end.iter().any(|r| line.contains(r)) {
            return back;
        }
        if env_lists.lists_end.iter().any(|r| line.contains(r)) {
            back = back.wrapping_add(2);
        } else {
            back = back.wrapping_add(1);
        }
    } else if envs.item {
        back = back.wrapping_add(1);
    }
    back
}

/// Calculate the indentation of a line and update the state
pub fn calculate_indent(
    line: &str,
    state: &mut State,
    logs: &mut Vec<Log>,
    file: &str,
    args: &Args,
    pattern: &Pattern,
    env_lists: &EnvLists,
) -> Indent {
    let comment_index = find_comment_index(line);
    let line_strip = remove_comment(line, comment_index);
    let envs = get_envs(line_strip, pattern);
    let diff = get_diff(line_strip, &envs, env_lists);
    let back = get_back(line_strip, &envs, state, env_lists);
    let actual = state.indent.actual.wrapping_add(diff);
    let visual = state.indent.actual.wrapping_sub(back);

    if args.verbosity == log::LevelFilter::Trace {
        record_line_log(
            logs,
            Trace,
            file,
            state.linum_new,
            state.linum_old,
            line,
            &format!("Indent: actual = {actual}, visual = {visual}:"),
        );
    }

    if visual < 0 || actual < 0 {
        record_line_log(
            logs,
            Warn,
            file,
            state.linum_new,
            state.linum_old,
            line,
            "Indent is negative.",
        );
        if state.linum_first_negative_indent.is_none() {
            state.linum_first_negative_indent = Some(state.linum_new);
        }
    }

    if visual == 0 {
        state.linum_last_zero_indent = state.linum_new;
    }

    let indent = Indent {
        actual,
        visual: max(visual, 0),
    };
    state.indent = indent.clone();
    indent
}

/// Apply the indentation to a line
pub fn apply_indent(line: &str, indent_length: usize, indent_char: char) -> String {
    let trimmed = line.trim_start();
    if trimmed.is_empty() {
        return String::new();
    }
    let mut new_line = String::with_capacity(indent_length + trimmed.len());
    for _ in 0..indent_length {
        new_line.push(indent_char);
    }
    new_line.push_str(trimmed);
    new_line
}
EOF
