//! Wrapping of long lines

use crate::args::Args;
use crate::comments::find_comment_index;
use crate::format::State;
use crate::logging::{record_line_log, Log};
use crate::regexes::VERBS;
use log::Level::{Trace, Warn};

/// Check if a line needs wrapping
pub fn needs_wrap(line: &str, indent_length: usize, args: &Args) -> bool {
    args.wrap && (line.chars().count() + indent_length > args.wraplen)
}

/// Check whether a character is a suitable place to break the line
fn is_wrap_point(
    i_byte: usize,
    c: char,
    prev_c: Option<char>,
    inside_verb: bool,
    line_len: usize,
    args: &Args,
) -> bool {
    args.wrap_chars.contains(&c)
        && prev_c != Some('\\')
        && !inside_verb
        && (i_byte + 1 < line_len)
}

/// Find the end of an inline verbatim command
fn get_verb_end(verb_start: Option<usize>, line: &str) -> Option<usize> {
    let start = verb_start?;
    line[start..]
        .match_indices(['|', '+'])
        .nth(1)
        .map(|(i, _)| i + start)
}

/// Check whether a byte index is inside an inline verbatim command
fn is_inside_verb(
    i_byte: usize,
    contains_verb: bool,
    verb_start: Option<usize>,
    verb_end: Option<usize>,
) -> bool {
    if contains_verb {
        (verb_start.unwrap() <= i_byte) && (i_byte <= verb_end.unwrap())
    } else {
        false
    }
}

/// Find the best place to break a long line
///
/// Returns the byte index of the last byte of the wrapping character.
fn find_wrap_point(line: &str, indent_length: usize, args: &Args) -> Option<usize> {
    let mut wrap_point: Option<usize> = None;
    let mut prev_c: Option<char> = None;
    let contains_verb = VERBS.iter().any(|v| line.contains(v));
    let verb_start: Option<usize> = if contains_verb {
        VERBS.iter().filter_map(|v| line.find(v)).min()
    } else {
        None
    };
    let verb_end = get_verb_end(verb_start, line);
    let mut after_non_percent = false;
    let wrap_boundary = args.wrapmin.saturating_sub(indent_length);
    let line_len = line.len();

    for (i_char, (i_byte, c)) in line.char_indices().enumerate() {
        if i_char >= wrap_boundary && wrap_point.is_some() {
            break;
        }
        let inside_verb =
            is_inside_verb(i_byte, contains_verb, verb_start, verb_end);
        if is_wrap_point(i_byte, c, prev_c, inside_verb, line_len, args) {
            if after_non_percent {
                wrap_point = Some(i_byte + c.len_utf8() - 1);
            }
        } else if c != '%' {
            after_non_percent = true;
        }
        prev_c = Some(c);
    }

    wrap_point
}

/// Wrap a long line into a prefix and a suffix
pub fn apply_wrap<'a>(
    line: &'a str,
    indent_length: usize,
    state: &State,
    file: &str,
    args: &Args,
    logs: &mut Vec<Log>,
) -> Option<[&'a str; 3]> {
    if args.verbosity == log::LevelFilter::Trace {
        record_line_log(
            logs,
            Trace,
            file,
            state.linum_new,
            state.linum_old,
            line,
            "Wrapping long line.",
        );
    }
    let wrap_point = find_wrap_point(line, indent_length, args);
    let comment_index = find_comment_index(line);

    match wrap_point {
        Some(p) if p <= args.wraplen => {}
        _ => {
            record_line_log(
                logs,
                Warn,
                file,
                state.linum_new,
                state.linum_old,
                line,
                "Line cannot be wrapped.",
            );
        }
    }

    wrap_point.map(|p| {
        let this_line = &line[0..=p];
        let next_line_start = comment_index
            .and_then(|c| if p > c { Some("% ") } else { None })
            .unwrap_or_default();
        let next_line = &line[p + 1..];
        [this_line, next_line_start, next_line]
    })
}
