//! Utilities for performing text substitutions

use crate::args::{Args, TabChar};
use crate::comments::find_comment_index;
use crate::format::State;
use crate::logging::{record_line_log, Log};
use crate::pattern::Pattern;
use crate::regexes::{RE_NEWLINES, RE_SPLITTING_SHARED_LINE_CAPTURE, RE_TRAIL, VERBS};
use log::Level::Trace;

/// Remove multiple consecutive blank lines
pub fn remove_extra_newlines(text: &str) -> String {
    RE_NEWLINES.replace_all(text, "\n\n").to_string()
}

/// Replace tabs with spaces
pub fn remove_tabs(text: &str, args: &Args) -> String {
    let replace = " ".repeat(args.tabsize as usize);
    text.replace('\t', &replace)
}

/// Remove trailing spaces from each line
pub fn remove_trailing_spaces(text: &str) -> String {
    RE_TRAIL.replace_all(text, "\n").to_string()
}

/// Remove trailing blank lines at the end of the file
pub fn remove_trailing_blank_lines(text: &str) -> String {
    let mut new_text = text.trim_end().to_string();
    new_text.push('\n');
    new_text
}

/// Clean the source text before formatting
pub fn clean_text(text: &str, args: &Args) -> String {
    let mut text = remove_extra_newlines(text);
    if args.tabchar != TabChar::Tab {
        text = remove_tabs(&text, args);
    }
    remove_trailing_spaces(&text)
}

/// Check if a line contains a pattern which should be on its own line
pub fn needs_split(line: &str, pattern: &Pattern) -> bool {
    // Do not split lines containing inline verbatim
    if VERBS.iter().any(|v| line.contains(v)) {
        return false;
    }
    if !pattern.contains_splitting {
        return false;
    }
    let Some(captures) = RE_SPLITTING_SHARED_LINE_CAPTURE.captures(line) else {
        return false;
    };
    let env_start = captures.name("env").unwrap().start();
    // Only split if the pattern is not inside a comment
    find_comment_index(line).is_none_or(|c| env_start <= c)
}

/// Split a line into the part before and the part after a pattern
pub fn split_line<'a>(
    line: &'a str,
    state: &State,
    file: &str,
    args: &Args,
    logs: &mut Vec<Log>,
) -> (&'a str, &'a str) {
    let captures = RE_SPLITTING_SHARED_LINE_CAPTURE.captures(line).unwrap();
    let this_line = captures.name("prev").unwrap().as_str();
    let next_line = captures.name("env").unwrap().as_str();
    if args.verbosity == log::LevelFilter::Trace {
        record_line_log(
            logs,
            Trace,
            file,
            state.linum_new,
            state.linum_old,
            line,
            "Placing environment on new line.",
        );
    }
    (this_line, next_line)
}
