fn is_wrap_point(
    i_byte: usize,
    c: char,
    prev_c: Option<char>,
    inside_verb: bool,
    line_len: usize,
    args: &Args,
) -> bool {
    args.wrap_chars.contains(&c)
        && prev_c != Some('\\')
        && !inside_verb
        && (i_byte + 1 < line_len)
}

/// Find the end of an inline verbatim command
fn get_verb_end(verb_start: Option<usize>, line: &str) -> Option<usize> {
    let start = verb_start?;
    line[start..]
        .match_indices(['|', '+'])
        .nth(1)
        .map(|(i, _)| i + start)
}

