use crate::pattern::Pattern;
use crate::subs::{
    clean_text, needs_split, remove_trailing_blank_lines,
    remove_trailing_spaces, split_line,
};
use crate::verbatim::{get_verbatim, Verbatim};
use crate::wrap::{apply_wrap, needs_wrap};
use log::Level::{Info, Warn};
use std::iter::zip;

/// Environment names in the forms needed for matching
pub struct EnvLists {
    pub lists_begin: Vec<String>,
    pub lists_end: Vec<String>,
    pub verbatims_begin: Vec<String>,
    pub verbatims_end: Vec<String>,
    pub no_indent_begin: Vec<String>,
    pub no_indent_end: Vec<String>,
}

impl EnvLists {
    fn new(args: &Args) -> Self {
        let begin = |l: &Vec<String>| -> Vec<String> {
            l.iter().map(|e| format!("\\begin{{{e}}}")).collect()
        };
        let end = |l: &Vec<String>| -> Vec<String> {
            l.iter().map(|e| format!("\\end{{{e}}}")).collect()
        };
        Self {
            lists_begin: begin(&args.lists),
            lists_end: end(&args.lists),
            verbatims_begin: begin(&args.verbatims),
            verbatims_end: end(&args.verbatims),
            no_indent_begin: begin(&args.no_indent_envs),
            no_indent_end: end(&args.no_indent_envs),
        }
    }
}

/// Information on the current state during formatting
#[derive(Clone, Debug)]
pub struct State {
    /// Corresponding line number in the original file
    pub linum_old: usize,
    /// Corresponding line number in the formatted file
    pub linum_new: usize,
    /// Ignored status of the current line
    pub ignore: Ignore,
    /// Indentation status of the current line
    pub indent: Indent,
    /// Verbatim status of the current line
    pub verbatim: Verbatim,
    /// Line number in the new file of the last non-indented line
    pub linum_last_zero_indent: usize,
    /// Line number in the new file of the first negatively indented line
    pub linum_first_negative_indent: Option<usize>,
}

impl State {
    /// Construct a new default state
    pub fn new() -> Self {
        Self {
            linum_old: 1,
            linum_new: 1,
            ignore: Ignore::default(),
            indent: Indent::default(),
            verbatim: Verbatim::default(),
            linum_last_zero_indent: 1,
            linum_first_negative_indent: None,
        }
    }
}

/// Check if the line should be left untouched, updating the state
fn set_ignore_and_report(
    line: &str,
    temp_state: &mut State,
    logs: &mut Vec<Log>,
    file: &str,
    env_lists: &EnvLists,
) -> bool {
    temp_state.ignore = get_ignore(line, temp_state, logs, file);
    temp_state.verbatim = get_verbatim(
        line,
        temp_state,
        logs,
        file,
        &env_lists.verbatims_begin,
        &env_lists.verbatims_end,
    );
    temp_state.verbatim.visual || temp_state.ignore.visual
}

/// Format a LaTeX file
pub fn format_file(old_text: &str, file: &str, args: &Args, logs: &mut Vec<Log>) -> String {
    record_file_log(logs, Info, file, "Formatting started.");
    let old_text = clean_text(old_text, args);
    let mut old_lines = zip(1.., old_text.lines());
    let mut state = State::new();
    let mut queue: Vec<(usize, String)> = vec![];
    let mut new_text = String::with_capacity(2 * old_text.len());
    let indent_char = match args.tabchar {
        TabChar::Tab => '\t',
        TabChar::Space => ' ',
    };
    let env_lists = EnvLists::new(args);
    let tabsize = args.tabsize as i8;

    loop {
        if let Some((linum_old, mut line)) = queue.pop() {
            let pattern = Pattern::new(&line);
            let mut temp_state = state.clone();
            temp_state.linum_old = linum_old;
            if !set_ignore_and_report(&line, &mut temp_state, logs, file, &env_lists) {
                if needs_split(&line, &pattern) {
                    let (this_line, next_line) =
                        split_line(&line, &temp_state, file, args, logs);
                    queue.push((linum_old, next_line.to_string()));
                    line = this_line.to_string();
                }
                let indent = calculate_indent(
                    &line,
                    &mut temp_state,
                    logs,
                    file,
                    args,
                    &pattern,
                    &env_lists,
                );
                let indent_length = usize::try_from(indent.visual.wrapping_mul(tabsize))
                    .expect("Visual indent is non-negative.");
                if needs_wrap(line.trim_start(), indent_length, args) {
                    let wrapped_lines = apply_wrap(
                        line.trim_start(),
                        indent_length,
                        &temp_state,
                        file,
                        args,
                        logs,
                    );
                    if let Some([this_line, next_line_start, next_line]) = wrapped_lines {
                        queue.push((linum_old, [next_line_start, next_line].concat()));
                        queue.push((linum_old, this_line.to_string()));
                        continue;
                    }
                }
                line = apply_indent(&line, indent_length, indent_char);
            }
            state = temp_state;
            new_text.push_str(&line);
            new_text.push('\n');
            state.linum_new += 1;
        } else if let Some((linum_old, line)) = old_lines.next() {
            queue.push((linum_old, line.to_string()));
        } else {
            break;
        }
    }

    if state.indent.actual != 0 {
        let message = format!(
            "Indent does not return to zero. Last non-indented line is line {}",
            state.linum_last_zero_indent
        );
        record_file_log(logs, Warn, file, &message);
    }

    if let Some(linum) = state.linum_first_negative_indent {
        let message =
            format!("Negative indents. First negatively indented line is line {linum}");
        record_file_log(logs, Warn, file, &message);
    }

    new_text = remove_trailing_spaces(&new_text);
    new_text = remove_trailing_blank_lines(&new_text);
    record_file_log(logs, Info, file, "Formatting complete.");
    new_text
}
