//! Reading input

use crate::logging::{record_file_log, Log};
use log::Level::{Error, Trace};
use std::fs;
use std::io::Read;
use std::path::Path;

/// Read the contents of a file
pub fn read(file: &Path, logs: &mut Vec<Log>) -> Option<String> {
    if let Ok(text) = fs::read_to_string(file) {
        return Some(text);
    }
    record_file_log(logs, Error, &file.to_string_lossy(), "Could not open file.");
    None
}

/// Read the contents of stdin
pub fn read_stdin(logs: &mut Vec<Log>) -> Option<String> {
    let mut text = String::new();
    match std::io::stdin().read_to_string(&mut text) {
        Ok(bytes) => {
            record_file_log(logs, Trace, "<stdin>", &format!("Read {bytes} bytes."));
            Some(text)
        }
        Err(e) => {
            record_file_log(
                logs,
                Error,
                "<stdin>",
                &format!("Could not read from stdin: {e}"),
            );
            None
        }
    }
}
