    record_file_log(logs, Error, &file.to_string_lossy(), "Could not open file.");
    None
}

/// Read the contents of stdin
pub fn read_stdin(logs: &mut Vec<Log>) -> Option<String> {
    let mut text = String::new();
    match std::io::stdin().read_to_string(&mut text) {
        Ok(bytes) => {
            record_file_log(logs, Trace, "<stdin>", &format!("Read {bytes} bytes."));
            Some(text)
        }
        Err(e) => {
            record_file_log(
                logs,
