//! Writing output

use crate::args::Args;
use crate::logging::{record_file_log, Log};
use log::Level::Error;
use std::fs;
use std::path::Path;

/// Write the formatted text to a file
fn write_file(file: &Path, text: &str) {
    fs::write(file, text).expect("Could not write the file");
}

/// Handle the formatted text according to the arguments,
/// returning an exit code
pub fn process_output(
    args: &Args,
    file: &Path,
    text: &str,
    new_text: &str,
    logs: &mut Vec<Log>,
) -> u8 {
    if args.print {
        print!("{new_text}");
        0
    } else if args.check {
        if text == new_text {
            0
        } else {
            record_file_log(logs, Error, &file.to_string_lossy(), "Incorrect formatting.");
            1
        }
    } else if text != new_text {
        write_file(file, new_text);
        u8::from(args.fail_on_change)
    } else {
        0
    }
}
