{"command":"cd /workspace && git add -A && git commit -qm "Print args line by line; cleanup" && cat > /tmp/cmp/fuzz4.py <<'EOF'
#!/usr/bin/env python3
import random, sys
sys.path.insert(0, "/tmp/cmp")
from run import compare

ATOMS = ["a", "bb", "ccc", "dddd", "eeeee", "ffffff", "%", "%%", "\\%", "\\\\", "\\ ", "{", "}", "[", "]", "(", ")",
         "\\item", "\\item[", "\\itemx", "\\item{}", "\\begin{itemize}", "\\end{itemize}", "\\begin{a}", "\\end{a}",
         "\\section{", "\\section*{", "\\subsubsection{", "\\chapter{", "\\part*{", "\\verb|", "\\verb+", "|", "+",
         "\\mintinline", "。", "字", "\t", "\\begin{verbatim}", "\\end{verbatim}", "% tex-fmt: skip", "% tex-fmt: off", "% tex-fmt: on",
         "\\begin{document}", "\\end{document}", "\\begin{comment}", "\\end{comment}", " ", "  ", "\u00a0", "\r"]

def rand_line(rng):
    target = rng.choice([0, 5, 30, 60, 68, 69, 70, 71, 72, 78, 79, 80, 81, 82, 90, 120, 200])
    s = ""
    while len(s) < target:
        a = rng.choice(ATOMS)
        if rng.random() < 0.6:
            a = rng.choice(ATOMS[:6])
        s += a
        if rng.random() < 0.6:
            s += " "
    if rng.random() < 0.3:
        s = " " * rng.randint(1, 10) + s
    return s

if __name__ == "__main__":
    seed = int(sys.argv[1]); count = int(sys.argv[2])
    rng = random.Random(seed)
    fails = 0
    for i in range(count):
        doc = "\n".join(rand_line(rng) for _ in range(rng.randint(1, 30)))
        if rng.random() < 0.8:
            doc += "\n"
        args = ["-s", "--noconfig", "--trace"]
        r = rng.random()
        if r < 0.2:
            args += ["-l", str(rng.choice([0, 1, 2, 5, 10, 49, 50, 51, 60]))]
        elif r < 0.3:
            args += ["--usetabs"]
        elif r < 0.4:
            args += ["-t", str(rng.choice([0, 1, 4, 7]))]
        if not compare(f"fuzz4-{seed}-{i}", args, doc.encode(), {}):
            fails += 1
            open(f"/tmp/cmp/fail4_{seed}_{i}.tex", "w").write(doc)
    print(f"seed {seed}: {fails} failures out of {count}")
EOF
